using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleClearingReward", menuName = "Data/Rewards/BattleClearingReward", order = 0)]
public class BattleClearingReward : ClearingReward
{
	protected override Reward[] GetRewards()
	{
		Reward[] battleModifiedRewards = base.GetRewards();
		OnlySpecificChestRunModifier onlySpecificChestRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.OnlySpecificChestRunModifier;
		if (onlySpecificChestRunModifier != null)
		{
			battleModifiedRewards = onlySpecificChestRunModifier.GetBattleModifiedRewards(battleModifiedRewards);
		}
		DiceShortageRunModifier diceShortageRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.DiceShortageRunModifier;
		if (diceShortageRunModifier != null)
		{
			battleModifiedRewards = diceShortageRunModifier.GetBattleModifiedRewards(battleModifiedRewards);
		}
		ScorchedBattlefieldRunModifier scorchedBattlefieldRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.ScorchedBattlefieldRunModifier;
		if (scorchedBattlefieldRunModifier != null)
		{
			battleModifiedRewards = scorchedBattlefieldRunModifier.GetBattleModifiedRewards(battleModifiedRewards);
		}
		RestlessJourneyRunModifier restlessJourneyRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.RestlessJourneyRunModifier;
		if (restlessJourneyRunModifier != null)
		{
			battleModifiedRewards = restlessJourneyRunModifier.GetBattleModifiedRewards(battleModifiedRewards);
		}
		BlessedPathRunModifier blessedPathRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.BlessedPathRunModifier;
		if (blessedPathRunModifier != null)
		{
			battleModifiedRewards = blessedPathRunModifier.GetBattleModifiedRewards(battleModifiedRewards);
		}
		DraftDiceRunModifier draftDiceRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.DraftDiceRunModifier;
		if (draftDiceRunModifier != null && draftDiceRunModifier.IsTheChosenPool)
		{
			battleModifiedRewards = draftDiceRunModifier.GetBattleModifiedRewards(battleModifiedRewards);
		}
		return battleModifiedRewards;
	}
}
